function finalString(s) {
  const front = [];
  const back = [];
  let flipped = false;

  for (const ch of s) {
    if (ch === 'i') {
      flipped = !flipped;
    } else if (flipped) {
      front.push(ch);
    } else {
      back.push(ch);
    }
  }

  const text = front.reverse().concat(back);
  if (flipped) {
    text.reverse();
  }
  return text.join('');
}

