function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const length = size === 'large' ? pick(90, 100) : pick(1, 10);
  const chance = [0.1, 0.3, 0.6][pick(0, 2)];
  const letters = size === 'large' ? 'abcdefghjklmnopqrstuvwxyz' : 'abcde';
  let s = letters[pick(0, letters.length - 1)];
  while (s.length < length) {
    s += rand() < chance ? 'i' : letters[pick(0, letters.length - 1)];
  }
  return [s];
}
